async function loadBoard() { const response = await fetch(`/api/projects/${encodeURIComponent(boardState.projectId)}/state`); if (!response.ok) throw new Error('Project state unavailable'); const state = await response.json(); boardState.data = state.plan; boardState.project = state.project; boardState.policy = state.policy || null; boardState.runtimeStatus = state.status; boardState.report = state.report; boardState.currentTask = state.currentTask; boardState.events = state.events || []; boardState.queue = state.queue || []; boardState.claims = state.claims || {}; boardState.health = state.health || null; document.getElementById('overview-project').textContent = `${state.project.name} / local`; document.getElementById('overview-branch').textContent = state.git?.branch || 'не Git-проект'; window.harnessBoardReady = true; renderBoard(); }
async function saveBoard() { boardState.data.events = (boardState.data.events || []).slice(-100); const payload = JSON.stringify(boardState.data); saveQueue = saveQueue.catch(() => {}).then(async () => { const response = await fetch(`/api/projects/${encodeURIComponent(boardState.projectId)}/plan`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: payload }); if (response.status === 409) { toast('План изменён в другом окне — сначала обновите проект'); throw new Error('Plan conflict'); } if (!response.ok) throw new Error('Plan save failed'); boardState.data = await response.json(); }); return saveQueue; }
function refreshGlobalStatuses() { const cards = boardState.data.cards || []; let changed = false; cards.filter((card) => card.isGlobal || card.type === 'global').forEach((group) => { const children = cards.filter((card) => card.parentId === group.id); if (!children.length) return; const next = children.every((card) => card.status === 'done') ? 'done' : children.some((card) => card.status === 'blocked') ? 'blocked' : children.some((card) => ['working', 'review', 'approval'].includes(card.status)) ? 'working' : children.some((card) => card.status === 'ready') ? 'ready' : 'inbox'; if (group.status !== next) { group.status = next; group.updatedAt = new Date().toISOString(); changed = true; } }); return changed; }
function renderBoard() {
  const { columns, cards } = boardState.data;
  refreshGlobalStatuses();
  const query = boardState.filterText.toLowerCase();
  const today = new Date().toISOString().slice(0, 10); const hasDependencies = (card) => Boolean(card.dependencies?.length); const hasDeadline = (card) => Boolean(card.dueDate);
  const visibleCards = cards.filter((card) => (!query || `${card.title} ${card.description || ''} ${card.agent || ''} ${card.executor || ''}`.toLowerCase().includes(query)) && (boardState.filterPriority === 'all' || card.priority === boardState.filterPriority) && (boardState.filterExecutor === 'all' || (card.executor || 'codex') === boardState.filterExecutor) && (boardState.filterDependency === 'all' || (boardState.filterDependency === 'has' && hasDependencies(card) || boardState.filterDependency === 'none' && !hasDependencies(card))) && (boardState.filterDeadline === 'all' || (boardState.filterDeadline === 'overdue' && hasDeadline(card) && card.dueDate < today && card.status !== 'done') || (boardState.filterDeadline === 'upcoming' && hasDeadline(card)) || (boardState.filterDeadline === 'none' && !hasDeadline(card))) && (boardState.view === 'all' || boardState.view === 'timeline' || (boardState.view === 'mine' && (card.executor || 'codex') === 'human') || (boardState.view === 'blocked' && card.status === 'blocked') || (boardState.view === 'review' && card.status === 'review')));
  const filtering = Boolean(query || boardState.filterPriority !== 'all' || boardState.filterExecutor !== 'all' || boardState.filterDependency !== 'all' || boardState.filterDeadline !== 'all' || boardState.view !== 'all');
  if (boardState.view === 'timeline') { renderTimeline(visibleCards); return; }
  if (boardState.view === 'dependencies') { renderDependencyGraph(visibleCards); return; }
  const globals = cards.filter((card) => card.isGlobal || card.type === 'global');
  const globalIds = new Set(globals.map((card) => card.id));
  const globalMarkup = globals.filter((group) => visibleCards.includes(group) || cards.some((card) => card.parentId === group.id && visibleCards.includes(card))).map((group) => { const children = cards.filter((card) => card.parentId === group.id); const completed = children.filter((card) => card.status === 'done').length; const collapsed = boardState.collapsedGroups.has(group.id); return `<section class="global-task ${collapsed ? 'is-collapsed' : ''}" data-global-id="${group.id}"><div class="global-task-main"><button class="global-toggle" data-toggle-global="${group.id}" aria-expanded="${!collapsed}">${collapsed ? '▶' : '▼'}</button><div><span class="global-kicker">ГЛОБАЛЬНАЯ ЗАДАЧА</span><h3>${boardEscapeHtml(group.title)}</h3><p>${boardEscapeHtml(group.description || 'Раскройте задачу на подзадачи по колонкам.')}</p></div><span class="global-progress">${completed}/${children.length || 0} подзадач</span><button class="global-add" data-add-parent="${group.id}">＋ Подзадача</button><button class="card-menu" aria-label="Редактировать глобальную задачу" onclick="openCard('${group.id}')">•••</button></div></section>`; }).join('');
  const queueMarkup = boardState.queue.length ? `<section class="ai-inbox"><div><span class="global-kicker">ВХОДЯЩИЕ ДЛЯ ИИ</span><h3>${boardState.queue.length} задач в очереди</h3><p>Сначала запускаются высокий приоритет и ближайший дедлайн.</p></div><div class="ai-queue-list">${boardState.queue.slice(0, 5).map((item) => `<div class="ai-queue-item"><strong>${boardEscapeHtml(item.title || item.taskId)}</strong><span>${boardEscapeHtml(item.priority || 'medium')}${item.dueDate ? ` · ${boardEscapeHtml(item.dueDate)}` : ''}</span></div>`).join('')}</div><button class="global-add" data-dispatch-queue ${boardState.runtimeStatus?.status === 'working' ? 'disabled' : ''}>${boardState.runtimeStatus?.status === 'working' ? 'Ожидает завершения' : 'Запустить следующую'}</button></section>` : '';
  boardEl.innerHTML = `${queueMarkup}${globalMarkup ? `<div class="global-tasks-heading"><span>ГЛОБАЛЬНЫЕ ЗАДАЧИ</span><small>Подзадачи распределены по статусным колонкам</small></div><div class="global-tasks">${globalMarkup}</div>` : ''}${columns.map((column) => { const items = visibleCards.filter((card) => card.status === column.id && !globalIds.has(card.id) && (!card.parentId || !boardState.collapsedGroups.has(card.parentId))); return `<section class="board-column" data-status="${column.id}"><div class="column-heading"><h3>${tx(column.id, column.title)}</h3><span class="column-count">${items.length}</span></div><div class="column-cards">${items.map(renderCard).join('')}${items.length || !filtering ? '' : `<div class="filter-empty">${tx('noMatches', 'Нет совпадений')}</div>`}<button class="drop-hint" data-add-status="${column.id}">${tx('addStep', '＋ Добавить шаг')}</button></div></section>`; }).join('')}`;
  const runtime = boardState.runtimeStatus?.status && boardState.runtimeStatus.status !== 'idle' ? ` · Codex: ${boardState.runtimeStatus.status}` : '';
  const syncTime = boardState.health?.readAt ? ` · ${tx('sync', 'синхр.')} ${new Date(boardState.health.readAt).toLocaleTimeString(languageLocale())}` : '';
  document.getElementById('board-summary').textContent = `${cards.length} ${tx('steps', 'шагов')} · ${cards.filter((card) => card.status === 'done').length} ${tx('completed', 'завершено')}${runtime}${syncTime} · ${boardState.policy?.label || 'Политика не задана'} · ${boardState.project?.path || tx('local', 'локальный проект')}`;
  if (boardState.health?.warnings?.length) toast(`Проблема файлового моста: ${boardState.health.warnings[0]}`);
  boardEl.querySelectorAll('[data-card-id]').forEach((card) => { card.addEventListener('dragstart', () => { boardState.dragId = card.dataset.cardId; card.classList.add('dragging'); }); card.addEventListener('dragend', () => { boardState.dragId = null; card.classList.remove('dragging'); }); card.addEventListener('dblclick', () => openCard(card.dataset.cardId)); });
  boardEl.querySelectorAll('.board-column').forEach((column) => { column.addEventListener('dragover', (event) => { event.preventDefault(); column.classList.add('drag-over'); }); column.addEventListener('dragleave', () => column.classList.remove('drag-over')); column.addEventListener('drop', () => { column.classList.remove('drag-over'); moveCard(boardState.dragId, column.dataset.status); }); });
  boardEl.querySelectorAll('[data-add-status]').forEach((button) => button.addEventListener('click', () => openCard(null, button.dataset.addStatus)));
  boardEl.querySelectorAll('[data-toggle-global]').forEach((button) => button.addEventListener('click', () => { const id = button.dataset.toggleGlobal; if (boardState.collapsedGroups.has(id)) boardState.collapsedGroups.delete(id); else boardState.collapsedGroups.add(id); localStorage.setItem('harness-collapsed-groups', JSON.stringify([...boardState.collapsedGroups])); renderBoard(); }));
  boardEl.querySelectorAll('[data-add-parent]').forEach((button) => button.addEventListener('click', () => openCard(null, 'ready', button.dataset.addParent)));
  boardEl.querySelectorAll('[data-run-id]').forEach((button) => button.addEventListener('click', () => runCard(button.dataset.runId)));
  boardEl.querySelectorAll('[data-approve-id]').forEach((button) => button.addEventListener('click', () => approveCard(button.dataset.approveId)));
  boardEl.querySelectorAll('[data-action-id]').forEach((button) => button.addEventListener('click', () => performCardAction(button.dataset.actionId, button.dataset.action)));
  boardEl.querySelectorAll('[data-release-id]').forEach((button) => button.addEventListener('click', async () => { await releaseCard(button.dataset.releaseId); renderBoard(); toast('Задача освобождена для другого исполнителя'); }));
  boardEl.querySelectorAll('[data-dispatch-queue]').forEach((button) => button.addEventListener('click', async () => { const response = await fetch(`/api/projects/${encodeURIComponent(boardState.projectId)}/queue/next`, { method: 'POST' }); const result = await response.json(); if (!response.ok) return toast(result.error || 'Очередь пока занята'); toast(result.dispatched ? 'Следующая задача передана ИИ' : 'Очередь пуста'); await syncProject(); }));
}
function renderCard(card) {
  const controls = card.status === 'ready' ? `<button class="card-run" data-run-id="${card.id}">${tx('run', '▶ Запустить')}</button>`
    : card.status === 'approval' && card.paused ? `<div class="card-running">${tx('paused', 'Ⅱ Исполнитель на паузе')}</div><div class="card-actions"><button class="card-action" data-action-id="${card.id}" data-action="resume">${tx('resume', '▶ Продолжить')}</button><button class="card-action danger-action" data-action-id="${card.id}" data-action="cancel">${tx('cancelTask', 'Отменить')}</button></div>`
    : card.status === 'approval' ? `<button class="card-run" data-approve-id="${card.id}">${tx('approve', '✓ Разрешить запуск')}</button>`
    : card.status === 'working' ? `<div class="card-running">${tx('running', '◌ Исполнитель в работе')}</div><div class="card-actions"><button class="card-action" data-action-id="${card.id}" data-action="pause">${tx('pause', 'Ⅱ Пауза')}</button><button class="card-action danger-action" data-action-id="${card.id}" data-action="cancel">${tx('cancelTask', 'Отменить')}</button></div>`
    : card.status === 'review' ? `<div class="card-actions"><button class="card-action" data-action-id="${card.id}" data-action="complete">${tx('complete', '✓ Подтвердить')}</button><button class="card-action" data-action-id="${card.id}" data-action="return">${tx('return', '↶ Вернуть')}</button></div>`
    : card.status === 'blocked' ? `<button class="card-run" data-action-id="${card.id}" data-action="retry">${tx('retry', '↻ Повторить')}</button>`
    : '';
  const dependencies = card.dependencies?.length ? `<span>↳ ${card.dependencies.length} ${tx('dependenciesShort', 'завис.')}</span>` : '';
  const executor = card.executor || 'codex'; const deadline = card.dueDate ? `<span>⌛ ${boardEscapeHtml(card.dueDate)}</span>` : ''; const estimate = card.estimateHours ? `<span>◷ ${boardEscapeHtml(card.estimateHours)}ч</span>` : ''; const mode = card.executionMode === 'auto' ? 'ИИ берет сам' : card.executionMode === 'approval' ? 'С подтверждением' : 'По указанию'; const claim = boardState.claims?.[card.id]; const claimInfo = claim ? `<span class="claim-info">♙ ${boardEscapeHtml(claim.claimedBy)} · до ${new Date(claim.expiresAt).toLocaleTimeString(languageLocale(), { hour: '2-digit', minute: '2-digit' })}</span>` : ''; const claimAction = claim?.claimedBy === agentId && card.status === 'working' ? `<button class="card-action claim-action" data-release-id="${card.id}">Освободить</button>` : '';
  return `<article class="board-card priority-${card.priority}" draggable="true" data-card-id="${card.id}"><div class="card-top"><span class="priority-label">${tx(card.priority, priorityNames[card.priority])}</span><button class="card-menu" aria-label="Редактировать шаг" onclick="openCard('${card.id}')">•••</button></div><h4>${boardEscapeHtml(card.title)}</h4><p>${boardEscapeHtml(card.description || 'Описание шага пока не добавлено.')}</p><div class="card-meta"><span>✦ ${boardEscapeHtml(tx(`executor.${executor}`, executorNames[executor] || executor))}</span><span>${boardEscapeHtml(mode)}</span><span>${card.criteria?.length || 0} крит.</span>${deadline}${estimate}${dependencies}${claimInfo}</div>${controls}${claimAction}</article>`;
}
function renderTimeline(cards) { const ordered = [...cards].sort((a, b) => String(a.dueDate || '9999').localeCompare(String(b.dueDate || '9999'))); boardEl.innerHTML = `<section class="timeline-board"><div class="timeline-heading"><h3>Timeline</h3><span>${ordered.length} ${tx('steps', 'шагов')}</span></div>${ordered.map((card) => `<article class="timeline-item priority-${card.priority}"><time>${boardEscapeHtml(card.dueDate || 'Без дедлайна')}</time><div><strong>${boardEscapeHtml(card.title)}</strong><small>${tx(card.status, card.status)} · ${boardEscapeHtml(card.estimateHours ? `${card.estimateHours}ч` : 'Оценка не задана')}</small></div></article>`).join('') || `<p class="history-empty">${tx('noMatches', 'Нет совпадений')}</p>`}</section>`; }
function renderDependencyGraph(cards) { const ids = new Set(cards.map((card) => card.id)); const nodes = cards.filter((card) => !card.isGlobal && card.type !== 'global').map((card) => { const dependencies = (card.dependencies || []).filter((dependency) => ids.has(dependency)); const dependencyNames = dependencies.map((dependency) => cards.find((item) => item.id === dependency)?.title || dependency); return `<article class="dependency-node priority-${card.priority}"><div><strong>${boardEscapeHtml(card.title)}</strong><small>${tx(card.status, card.status)} · ${dependencies.length ? `зависит от: ${boardEscapeHtml(dependencyNames.join(', '))}` : 'без зависимостей'}</small></div><span>${dependencies.length ? '←' : '•'}</span></article>`; }).join(''); boardEl.innerHTML = `<section class="dependency-graph"><div class="timeline-heading"><div><h3>Граф зависимостей</h3><p>Стрелка указывает на задачу, которая должна быть завершена раньше.</p></div><span>${cards.filter((card) => card.dependencies?.length).length} связей</span></div><div class="dependency-list">${nodes || `<p class="history-empty">${tx('noMatches', 'Нет совпадений')}</p>`}</div></section>`; }
function boardEscapeHtml(value) { return String(value).replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char])); }
function downloadExport(filename, type, content) { const url = URL.createObjectURL(new Blob([content], { type })); const link = document.createElement('a'); link.href = url; link.download = filename; link.click(); URL.revokeObjectURL(url); }
async function enableNotifications() { if (!('Notification' in window)) return toast('Уведомления не поддерживаются этим браузером'); const permission = await Notification.requestPermission(); localStorage.setItem('harness-notifications', permission); notificationsButton.textContent = permission === 'granted' ? '♢ Уведомления включены' : '♢ Уведомления'; toast(permission === 'granted' ? 'Локальные уведомления включены' : 'Разрешение на уведомления не выдано'); }
