function showProjectSettings() { const dialog = document.createElement('dialog'); dialog.className = 'project-settings-dialog'; const currentPolicy = boardState.project?.policy || 'development'; const currentAdapters = boardState.policy?.allowedAdapters || ['git-status', 'npm-test', 'npm-lint', 'npm-build']; const adapters = [['git-status', 'Git status'], ['npm-test', 'npm test'], ['npm-lint', 'npm run lint'], ['npm-build', 'npm run build']]; dialog.innerHTML = '<div class="dialog-heading"><div><div class="eyebrow">PROJECT POLICY</div><h2>Политика проекта</h2></div><button class="close-button" aria-label="Закрыть">×</button></div><label>Профиль<select class="settings-policy"><option value="safe">Строго безопасный</option><option value="development">Обычная разработка</option><option value="manual">Полный ручной контроль</option></select></label><p class="run-note">Профиль действует на сервере и не обходится прямым API-запросом.</p><div class="settings-adapters"><strong>Разрешённые адаптеры</strong>' + adapters.map(([id, label]) => '<label><input type="checkbox" value="' + id + '" ' + (currentAdapters.includes(id) ? 'checked' : '') + '> ' + label + '</label>').join('') + '</div><div class="dialog-actions"><button class="button secondary settings-cancel">Отмена</button><button class="button primary settings-save">Сохранить</button></div>'; document.body.append(dialog); dialog.querySelector('.settings-policy').value = currentPolicy; const close = () => { dialog.close(); dialog.remove(); }; dialog.querySelector('.close-button').onclick = close; dialog.querySelector('.settings-cancel').onclick = close; dialog.querySelector('.settings-save').onclick = async () => { const policy = dialog.querySelector('.settings-policy').value; const allowedAdapters = [...dialog.querySelectorAll('.settings-adapters input:checked')].map((input) => input.value); const response = await fetch('/api/projects/' + encodeURIComponent(boardState.projectId), { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ policy, allowedAdapters }) }); const result = await response.json(); if (!response.ok) return toast(result.error || 'Не удалось сохранить политику'); boardState.project = result; await loadBoard(); close(); toast('Политика проекта обновлена'); }; dialog.showModal(); }
async function manageVersions() { const response = await fetch(`/api/projects/${encodeURIComponent(boardState.projectId)}/plan/versions`); if (!response.ok) return toast('Не удалось загрузить версии плана'); const versions = await response.json(); const dialog = document.createElement('dialog'); dialog.className = 'versions-dialog'; dialog.innerHTML = `<div class="dialog-heading"><div><div class="eyebrow">PLAN HISTORY</div><h2>Версии плана</h2></div><button class="close-button" aria-label="Закрыть">×</button></div>${versions.length ? versions.map((version) => `<button class="history-row" data-version="${boardEscapeHtml(version.file)}"><strong>${boardEscapeHtml(version.file)}</strong><small>${new Date(version.createdAt).toLocaleString(languageLocale())}</small></button>`).join('') : '<p class="history-empty">Версий пока нет.</p>'}`; document.body.append(dialog); dialog.querySelector('.close-button').onclick = () => { dialog.close(); dialog.remove(); }; dialog.querySelectorAll('[data-version]').forEach((button) => button.addEventListener('click', async () => { const rollback = await fetch(`/api/projects/${encodeURIComponent(boardState.projectId)}/plan/rollback`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ file: button.dataset.version }) }); if (!rollback.ok) return toast('Не удалось откатить план'); const plan = await rollback.json(); boardState.data = plan; boardState.events.push({ type: 'plan_rollback', file: button.dataset.version, at: new Date().toISOString() }); dialog.close(); dialog.remove(); renderBoard(); toast('План восстановлен из версии'); })); dialog.showModal(); }
function exportMarkdown() { const columns = boardState.data.columns.map((column) => `## ${column.title}\n\n${boardState.data.cards.filter((card) => card.status === column.id).map((card) => `- **${card.title}** (${priorityNames[card.priority]}) — ${card.description || ''}`).join('\n') || '- Нет карточек'}`).join('\n\n'); return `# План проекта ${boardState.project?.name || ''}\n\nПуть: ${boardState.project?.path || ''}\n\n${columns}\n\n## Последние события\n\n${boardState.events.slice(-20).map((event) => `- ${event.at || ''} ${event.type || 'event'}${event.action ? `:${event.action}` : ''}`).join('\n')}`; }
function parseImportedCards(text, name) { const extension = name.toLowerCase().split('.').pop(); if (extension === 'json') { const parsed = JSON.parse(text); const githubIssues = Array.isArray(parsed) && parsed.some((issue) => issue.title && (issue.state || issue.html_url)) ? parsed : parsed.issues; if (Array.isArray(githubIssues)) return githubIssues.map((issue) => ({ title: issue.title, description: issue.body || '', priority: 'medium', status: issue.state === 'closed' ? 'done' : 'ready', executor: 'human', importSource: issue.html_url || 'github-issues', criteria: ['Импортированная задача'] })).filter((card) => card.title); const trelloCards = Array.isArray(parsed.cards) ? parsed.cards.filter((card) => card.name) : []; if (trelloCards.length) return trelloCards.map((card) => ({ title: card.name, description: card.desc || '', priority: 'medium', status: card.closed ? 'done' : 'ready', executor: 'human', importSource: card.shortUrl || 'trello', criteria: ['Импортированная задача'] })); return (Array.isArray(parsed) ? parsed : parsed.cards || parsed.plan?.cards || []).map((card) => ({ ...card, title: String(card.title || '').trim() })).filter((card) => card.title); } if (extension === 'csv') { const lines = text.split(/\r?\n/).filter(Boolean); const headers = lines.shift().split(',').map((item) => item.trim().toLowerCase()); return lines.map((line) => { const values = line.split(','); const row = Object.fromEntries(headers.map((header, index) => [header, values[index]?.trim() || ''])); return { title: row.title || row.name, description: row.description || '', priority: ['high', 'low'].includes(row.priority) ? row.priority : 'medium', status: ['inbox', 'ready', 'working', 'review', 'done'].includes(row.status) ? row.status : 'ready', executor: row.executor || 'human', criteria: ['Импортированная задача'] }; }).filter((card) => card.title); } return text.split(/\r?\n/).map((line) => { const match = line.match(/^\s*-\s*\[([ xX])\]\s*(.+)$/); return match ? { title: match[2].replace(/\s+$/, ''), description: 'Импортировано из Markdown', priority: 'medium', status: match[1].toLowerCase() === 'x' ? 'done' : 'ready', executor: 'human', criteria: ['Импортированная задача'] } : null; }).filter(Boolean); }
importInput.addEventListener('change', async () => { const file = importInput.files?.[0]; if (!file) return; try { const cards = parseImportedCards(await file.text(), file.name); if (!cards.length) throw new Error('В файле нет задач'); const now = new Date().toISOString(); cards.forEach((card, index) => boardState.data.cards.push({ ...card, id: uid(), updatedAt: now, importSource: file.name })); boardState.data.events.push({ type: 'import', source: file.name, count: cards.length, at: now }); await saveBoard(); renderBoard(); toast(`Импортировано задач: ${cards.length}`); } catch (error) { toast(`Ошибка импорта: ${error.message}`); } finally { importInput.value = ''; } });
function canEdit() { return ['owner', 'executor'].includes(userRolePicker.value); }
function canReview() { return ['owner', 'reviewer'].includes(userRolePicker.value); }
function openCard(id, status = 'inbox', parentId = '') { if (!canEdit()) { toast('Роль наблюдателя/ревьюера не позволяет редактировать карточку'); return; } boardState.editingId = id; const card = boardState.data.cards.find((item) => item.id === id); document.getElementById('card-dialog-title').textContent = card ? tx('editStep', 'Изменить шаг') : tx('newStep', 'Новый шаг'); boardFields.title.value = card?.title || ''; boardFields.description.value = card?.description || ''; boardFields.priority.value = card?.priority || 'medium'; boardFields.status.value = card?.status || status; globalField.value = card?.isGlobal || card?.type === 'global' ? 'global' : 'subtask'; parentField.innerHTML = '<option value="">Без глобальной задачи</option>' + boardState.data.cards.filter((item) => (item.isGlobal || item.type === 'global') && item.id !== id).map((item) => `<option value="${item.id}">${boardEscapeHtml(item.title)}</option>`).join(''); parentField.value = card?.parentId || parentId || ''; parentField.disabled = globalField.value === 'global'; executionField.value = card?.executionMode || 'manual'; dependencyField.value = (card?.dependencies || []).join(', '); executorField.value = card?.executor || 'codex'; commandField.value = card?.command || ''; adapterField.value = card?.adapter || ''; document.getElementById('card-dry-run').checked = card?.dryRun === true; dueDateField.value = card?.dueDate || ''; estimateField.value = card?.estimateHours || ''; roleField.value = card?.role || 'executor'; commentField.value = ''; const history = [...(boardState.data.events || []), ...(boardState.events || [])].filter((event) => event.cardId === id).slice(-8); cardHistory.textContent = card ? `${tx('history', 'История карточки')}\n${history.map((event) => `${event.at || ''} ${event.type || 'event'}${event.action ? `:${event.action}` : ''}${event.comment ? ` — ${event.comment}` : ''}`).join('\n') || tx('noHistory', 'Пока нет событий')}` : ''; cardHistory.hidden = !card; deleteCardButton.hidden = !card; boardDialog.showModal(); boardFields.title.focus(); }
async function deleteCard() { if (userRolePicker.value !== 'owner') { toast('Только владелец может удалить карточку'); return; } const card = boardState.data.cards.find((item) => item.id === boardState.editingId); if (!card || !window.confirm(`Удалить шаг «${card.title}»?`)) return; boardState.data.cards = boardState.data.cards.filter((item) => item.id !== card.id); boardState.data.events.push({ type: 'delete', cardId: card.id, title: card.title, at: new Date().toISOString() }); await saveBoard(); boardDialog.close(); renderBoard(); toast('Шаг удалён из плана'); }
async function moveCard(id, status) { if (!id) return; const card = boardState.data.cards.find((item) => item.id === id); if (!card || card.status === status) return; if (status === 'working') { boardState.data.events.push({ type: 'user_started_task', cardId: id, at: new Date().toISOString() }); await runCard(id, 'user'); return; } card.status = status; card.updatedAt = new Date().toISOString(); boardState.data.events.push({ type: 'move', cardId: id, status, at: card.updatedAt }); await saveBoard(); renderBoard(); }
const agentId = localStorage.getItem('harness-agent-id') || `harness-ui-${Math.random().toString(16).slice(2)}`; localStorage.setItem('harness-agent-id', agentId); async function claimCard(id) { const response = await fetch(`/api/projects/${encodeURIComponent(boardState.projectId)}/claim`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ taskId: id, claimedBy: agentId }) }); if (!response.ok) { const result = await response.json().catch(() => ({})); toast(result.error || 'Задача уже захвачена другим агентом'); return false; } boardState.claims[id] = await response.json(); return true; } async function heartbeatCard(id) { return claimCard(id); } async function releaseCard(id) { await fetch(`/api/projects/${encodeURIComponent(boardState.projectId)}/release`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ taskId: id, claimedBy: agentId }) }).catch(() => {}); delete boardState.claims[id]; } async function runCard(id) { const card = boardState.data.cards.find((item) => item.id === id); if (!card || !boardState.projectId || !(await claimCard(id))) return; const blockedBy = (card.dependencies || []).map((dependency) => boardState.data.cards.find((item) => item.id === dependency)).filter((dependency) => !dependency || dependency.status !== 'done'); if (blockedBy.length) { toast(`Сначала завершите зависимости: ${blockedBy.map((item) => item?.title || 'неизвестная карточка').join(', ')}`); await releaseCard(id); return; } if (card.priority === 'high' && !card.approved) { card.status = 'approval'; card.updatedAt = new Date().toISOString(); boardState.data.events.push({ type: 'approval_required', cardId: card.id, at: card.updatedAt }); await saveBoard(); await releaseCard(card.id); renderBoard(); toast('Высокий приоритет требует подтверждения'); return; } if (['powershell', 'cli'].includes(card.executor)) { if (!card.command && !card.adapter) { toast('Укажите команду или готовый адаптер в карточке'); await releaseCard(card.id); return; } const dryRun = card.dryRun === true; const executable = card.adapter || card.command; if (!dryRun && !window.confirm(`Запустить локального исполнителя в папке проекта?\n\n${executable}`)) { await releaseCard(card.id); return; } const response = await fetch(`/api/projects/${encodeURIComponent(boardState.projectId)}/command`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ taskId: card.id, title: card.title, command: card.command, adapter: card.adapter, executor: card.executor, executionMode: card.executionMode || 'manual', dryRun, confirmed: true }) }); const result = await response.json(); if (!response.ok) { toast(result.error || 'Команда не выполнена'); await releaseCard(card.id); return; } if (!dryRun) { card.status = result.status === 'completed' ? 'review' : 'blocked'; card.updatedAt = new Date().toISOString(); } boardState.data.events.push({ type: dryRun ? 'command_dry_run' : 'command_finished', source: result.source || card.adapter || card.executor, cardId: card.id, status: result.status || 'preview', at: new Date().toISOString() }); await saveBoard(); await releaseCard(card.id); renderBoard(); toast(dryRun ? 'Dry-run подготовлен — команда не запускалась' : `Локальный исполнитель: ${result.status}`); return; } const response = await fetch(`/api/projects/${encodeURIComponent(boardState.projectId)}/task`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ taskId: card.id, title: card.title, description: card.description, criteria: card.criteria, executor: card.executor || 'codex' }) }); if (!response.ok) { toast('Не удалось передать задачу исполнителю'); await releaseCard(card.id); return; } card.status = 'working'; card.updatedAt = new Date().toISOString(); boardState.data.events.push({ type: 'start_task', cardId: card.id, executor: card.executor || 'codex', at: card.updatedAt }); await saveBoard(); renderBoard(); toast('Задача записана в .harness/current-task.md'); }
async function approveCard(id) { const card = boardState.data.cards.find((item) => item.id === id); if (!card) return; card.approved = true; card.status = 'ready'; await saveBoard(); await runCard(id); }
async function performCardAction(id, action) {
  const card = boardState.data.cards.find((item) => item.id === id);
  if (!card) return;
  if (action === 'complete' && !canReview()) { toast('Только владелец или ревьюер может подтвердить результат'); return; }
  if (action === 'complete' && (!boardState.report.trim() || boardState.report.includes('Пока нет отчёта') || !card.criteria?.length)) { toast('Перед завершением нужен отчёт и хотя бы один критерий'); return; }
  const response = await fetch(`/api/projects/${encodeURIComponent(boardState.projectId)}/task`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ taskId: card.id, title: card.title, action, executor: card.executor || 'codex' }) });
  if (!response.ok) { toast('Не удалось передать команду Codex'); return; }
  const next = { pause: { status: 'approval', paused: true }, resume: { status: 'working', paused: false }, cancel: { status: 'blocked', cancelled: true }, retry: { status: 'ready', cancelled: false }, complete: { status: 'done', completedByUser: true }, return: { status: 'working', approved: false } }[action];
  if (!next) return;
  Object.assign(card, next, { updatedAt: new Date().toISOString() });
  if (['complete', 'cancel'].includes(action)) await releaseCard(card.id);
  if (action === 'complete') {
    const opened = boardState.data.cards.filter((candidate) => candidate.status === 'blocked' && (candidate.dependencies || []).includes(card.id) && (candidate.dependencies || []).every((dependency) => boardState.data.cards.find((item) => item.id === dependency)?.status === 'done'));
    opened.forEach((candidate) => { candidate.status = 'ready'; candidate.updatedAt = new Date().toISOString(); });
    if (opened.length) toast(`Открыто зависимых задач: ${opened.length}`);
  }
  boardState.data.events.push({ type: 'task_control', cardId: card.id, action, at: card.updatedAt });
  await saveBoard();
  renderBoard();
  toast({ pause: 'Задача поставлена на паузу', resume: 'Задача продолжена', cancel: 'Задача отменена и заблокирована', retry: 'Задача возвращена в готовые', complete: 'Результат подтверждён', return: 'Задача возвращена в работу' }[action]);
}
async function setActiveProject(project) { boardState.projectId = project.id; boardState.project = project; localStorage.setItem('harness-project', project.id); await loadBoard(); }
function parseTaskPlan(markdown) { const source = String(markdown || ''); const jsonBlock = source.match(/```json\s*([\s\S]*?)```/i); if (jsonBlock) { try { const parsed = JSON.parse(jsonBlock[1]); const items = Array.isArray(parsed) ? parsed : parsed.plan; if (Array.isArray(items)) return items.filter((item) => item?.title).map((item, index) => ({ planKey: item.id || item.planKey || `json-${index + 1}`, title: String(item.title).trim(), description: String(item.description || ''), status: item.status === 'done' || item.completed === true ? 'done' : 'ready', dependencies: item.dependsOn || item.dependencies || [] })); } catch { /* fall back to Markdown */ } } const match = source.match(/##\s+План\s*\n([\s\S]*?)(?=\n##\s|$)/i); if (!match) return []; return match[1].split(/\r?\n/).map((line) => { const item = line.match(/^\s*-\s*\[([ xX])\]\s*(.+)$/); if (!item) return null; const keyMatch = item[2].match(/^\[plan:([^\]]+)\]\s*/i); const clean = keyMatch ? item[2].slice(keyMatch[0].length) : item[2]; const parts = clean.split(/\s+—\s+/); return { planKey: keyMatch?.[1] || `legacy-${Date.now()}-${Math.random().toString(16).slice(2)}`, title: parts[0].trim(), description: parts.slice(1).join(' — ').trim(), status: item[1].toLowerCase() === 'x' ? 'done' : 'ready', dependencies: [] }; }).filter(Boolean); }
function showPlanPreview(changes) { return new Promise((resolve) => { const dialog = document.createElement('dialog'); dialog.className = 'plan-preview-dialog'; dialog.innerHTML = `<div class="dialog-heading"><div><div class="eyebrow">PLAN PREVIEW</div><h2>Изменения плана LLM</h2></div><button class="close-button" aria-label="Закрыть">×</button></div><p class="run-note">Проверьте изменения перед применением к доске.</p><div class="plan-preview-list">${changes.map((change) => `<div class="plan-preview-row">${boardEscapeHtml(change)}</div>`).join('')}</div><div class="dialog-actions"><button class="button secondary" data-plan-decision="cancel">Отклонить</button><button class="button primary" data-plan-decision="apply">Применить план</button></div>`; document.body.append(dialog); const finish = (accepted) => { dialog.close(); dialog.remove(); resolve(accepted); }; dialog.querySelector('[data-plan-decision="cancel"]').onclick = () => finish(false); dialog.querySelector('.close-button').onclick = () => finish(false); dialog.querySelector('[data-plan-decision="apply"]').onclick = () => finish(true); dialog.showModal(); }); }
async function importTaskPlan(markdown, taskId) { const plan = parseTaskPlan(markdown); const hash = `${taskId}:${plan.map((item) => `${item.planKey}:${item.status}`).join('|')}`; if (!plan.length || !taskId || boardState.lastImportedTask === hash) return; const source = boardState.data.cards.find((card) => card.id === taskId); const global = source || boardState.data.cards.find((card) => card.title === plan[0]?.title && (card.isGlobal || card.type === 'global')) || { id: uid(), title: boardState.runtimeStatus?.title || 'План LLM', description: 'План автоматически импортирован из current-task.md', status: 'working', priority: 'high', isGlobal: true, type: 'global', criteria: ['План исполнителя импортирован'] }; const children = boardState.data.cards.filter((card) => card.parentId === global.id); const existing = new Map(children.map((card) => [card.planKey || card.title, card])); const planIds = new Map(plan.map((item) => [item.planKey, existing.get(item.planKey)?.id || uid()])); const changes = plan.map((item) => { const target = existing.get(item.planKey); return target ? `• обновить: ${target.title} → ${item.title}${item.status === 'done' ? ' [завершено]' : ''}` : `• добавить: ${item.title}${item.status === 'done' ? ' [завершено]' : ''}`; }); if (!(await showPlanPreview(changes))) { boardState.lastImportedTask = hash; return; } if (!source) boardState.data.cards.push(global); plan.forEach((item) => { const target = existing.get(item.planKey); if (target) { target.title = item.title; target.description = item.description; target.status = item.status; target.dependencies = (item.dependencies || []).map((dependency) => planIds.get(dependency) || dependency); } else boardState.data.cards.push({ ...item, id: planIds.get(item.planKey), dependencies: (item.dependencies || []).map((dependency) => planIds.get(dependency) || dependency), parentId: global.id, priority: 'medium', executor: 'codex', executionMode: 'manual', criteria: ['Подзадача из плана LLM'], updatedAt: new Date().toISOString() }); }); boardState.lastImportedTask = hash; boardState.data.events.push({ type: 'plan_imported_from_llm', taskId, count: plan.length, at: new Date().toISOString() }); await saveBoard(); toast(`План LLM синхронизирован: ${plan.length} подзадач`); }
async function startAutomaticCards() { if (boardState.autoStarting || boardState.runtimeStatus?.status === 'working') return; const candidate = boardState.data.cards.find((card) => card.status === 'ready' && card.executionMode === 'auto' && (card.executor || 'codex') === 'codex' && (card.dependencies || []).every((dependency) => boardState.data.cards.find((item) => item.id === dependency)?.status === 'done')); if (!candidate) return; boardState.autoStarting = true; try { await runCard(candidate.id, 'auto'); } finally { boardState.autoStarting = false; } }
async function syncProject() { if (!boardState.projectId || !boardState.data) return; const response = await fetch(`/api/projects/${encodeURIComponent(boardState.projectId)}/state`); if (!response.ok) return; const state = await response.json(); const previousStatus = boardState.lastRuntimeStatus; boardState.lastRuntimeStatus = state.status?.status || null; boardState.runtimeStatus = state.status; boardState.policy = state.policy || null; boardState.report = state.report; boardState.currentTask = state.currentTask; boardState.events = state.events || []; boardState.queue = state.queue || []; boardState.claims = state.claims || {}; boardState.health = state.health || null; const warning = state.health?.warnings?.[0] || ''; if (warning && warning !== boardState.lastWarning) { notifyLocal('Harness: требуется внимание', warning); boardState.lastWarning = warning; } if (!warning) boardState.lastWarning = ''; await importTaskPlan(state.currentTask, state.status?.taskId); const task = boardState.data.cards.find((card) => card.id === state.status?.taskId); if (task && state.status.status === 'working') await heartbeatCard(task.id); if (task && state.status.status === 'completed' && task.status === 'working') { task.status = 'review'; task.updatedAt = new Date().toISOString(); await releaseCard(task.id); await saveBoard(); toast('Codex завершил задачу — результат ожидает проверки'); } else if (task && state.status.status === 'failed' && task.status === 'working') { task.status = 'blocked'; task.updatedAt = new Date().toISOString(); await releaseCard(task.id); await saveBoard(); toast('Codex сообщил об ошибке — задача заблокирована'); } if (previousStatus && previousStatus !== state.status?.status && ['completed', 'failed'].includes(state.status?.status)) notifyLocal(state.status.status === 'completed' ? 'Harness: задача завершена' : 'Harness: задача завершилась ошибкой', state.status.title || 'Проверьте карточку и отчёт проекта'); renderBoard(); await startAutomaticCards(); }
function showReport() { const reportDialog = document.getElementById('report-dialog'); document.getElementById('report-meta').textContent = (boardState.project?.name || 'Проект') + ' · статус ' + (boardState.runtimeStatus?.status || 'idle') + ' · источник ' + (boardState.runtimeStatus?.source || boardState.runtimeStatus?.executor || 'user'); document.getElementById('report-content').textContent = boardState.report || 'Отчёт пока не создан.'; let eventsHeading = reportDialog.querySelector('.events-heading'); let eventsContent = reportDialog.querySelector('.events-content'); let eventsSearch = reportDialog.querySelector('.events-search'); let eventsType = reportDialog.querySelector('.events-type'); if (!eventsHeading) { eventsHeading = document.createElement('h3'); eventsHeading.className = 'events-heading'; eventsHeading.textContent = 'Аудит действий'; eventsSearch = document.createElement('input'); eventsSearch.className = 'events-search'; eventsSearch.placeholder = 'Фильтр по задаче, агенту или событию'; eventsSearch.setAttribute('aria-label', 'Фильтр аудита'); eventsType = document.createElement('select'); eventsType.className = 'events-type'; eventsType.innerHTML = '<option value="all">Все события</option><option value="task_claimed">Захваты</option><option value="task_released">Освобождения</option><option value="plan_saved">Изменения плана</option><option value="command_finished">Команды</option>'; eventsContent = document.createElement('pre'); eventsContent.className = 'report-content events-content'; reportDialog.append(eventsHeading, eventsSearch, eventsType, eventsContent); eventsSearch.addEventListener('input', () => renderEvents()); eventsType.addEventListener('change', () => renderEvents()); } const renderEvents = () => { const query = eventsSearch.value.trim().toLowerCase(); const type = eventsType.value; const events = boardState.events.filter((event) => (!query || JSON.stringify(event).toLowerCase().includes(query)) && (type === 'all' || event.type === type)); eventsContent.textContent = events.length ? events.slice(-100).map((event) => (event.at || '') + '  [' + (event.source || event.executor || event.claimedBy || 'user') + '] ' + (event.type || 'event') + (event.action ? ':' + event.action : '') + (event.title ? '  ' + event.title : '')).join('\n') : 'По фильтру событий нет.'; }; renderEvents(); reportDialog.showModal(); }
setInterval(() => syncProject().catch(() => {}), 4000);
