document.getElementById('suggest-plan').onclick = async () => { const suggestions = [{ title: 'Уточнить цель и ограничения', description: 'Зафиксировать ожидаемый результат и границы действий агента.', priority: 'high', status: 'ready', agent: 'Planner', criteria: ['Цель сформулирована', 'Ограничения понятны'] }, { title: 'Собрать контекст проекта', description: 'Найти релевантные файлы, решения и предыдущие результаты.', priority: 'medium', status: 'ready', agent: 'Researcher', criteria: ['Контекст приложен к шагу'] }, { title: 'Выполнить первый проверяемый результат', description: 'Сделать минимальное изменение и показать его пользователю.', priority: 'high', status: 'ready', agent: 'Builder', criteria: ['Результат можно проверить'] }]; suggestions.forEach((item) => boardState.data.cards.push({ ...item, id: uid(), updatedAt: new Date().toISOString() })); boardState.data.events.push({ type: 'suggest-plan', count: suggestions.length, at: new Date().toISOString() }); await saveBoard(); renderBoard(); toast('ИИ предложил 3 шага — их можно изменить перед запуском'); };
