cardForm.addEventListener('submit', async (event) => { if (event.submitter?.value === 'cancel') return; event.preventDefault(); if (!canEdit()) { toast('Текущая роль не может изменять карточку'); return; } const existing = boardState.data.cards.find((item) => item.id === boardState.editingId); const comment = commentField.value.trim(); const mentions = [...comment.matchAll(/@([\wа-яё-]+)/giu)].map((match) => match[1]); const value = { id: existing?.id || uid(), isGlobal: globalField.value === 'global', type: globalField.value === 'global' ? 'global' : 'subtask', parentId: globalField.value === 'global' ? null : (parentField.value || null), executionMode: executionField.value, title: boardFields.title.value.trim(), description: boardFields.description.value.trim(), priority: boardFields.priority.value, status: boardFields.status.value, executor: executorField.value, command: commandField.value.trim(), adapter: adapterField.value || null, dryRun: document.getElementById('card-dry-run').checked, dueDate: dueDateField.value || null, estimateHours: estimateField.value ? Number(estimateField.value) : null, role: roleField.value, agent: existing?.agent || 'Workspace agent', criteria: existing?.criteria || ['Результат проверен'], dependencies: dependencyField.value.split(',').map((item) => item.trim()).filter(Boolean), updatedAt: new Date().toISOString() }; if (!value.title) return; if (existing) Object.assign(existing, value); else boardState.data.cards.push(value); boardState.data.events.push({ type: existing ? 'edit' : 'create', cardId: existing?.id || value.id, executor: value.executor, role: value.role, comment: comment || undefined, mentions, at: value.updatedAt }); await saveBoard(); boardDialog.close(); renderBoard(); });
